def _project_event(event: Mapping[str, Any], dynamic_ids: Mapping[str, str]) -> tuple[Any, ...] | None:
    event_type = str(event.get("type") or "")
    post_id = str(event.get("postId") or "")
    dynamic_by_id = {post_id_value: text for text, post_id_value in dynamic_ids.items()}
    post_token = dynamic_by_id.get(post_id, post_id)
    if event_type == "notifications_marked_read":
        return (event_type,)
    if event_type == "post_created" and str(event.get("text") or "") in CREATED_POSTS:
        return (event_type, str(event.get("text") or ""))
    if event_type in {"post_like_toggled", "post_bookmark_toggled", "post_repost_toggled"}:
        target_ids = set(SEED_POSTS) | set(dynamic_by_id)
        if post_id in target_ids:
            return (event_type, post_token, event.get("active") is True)
    if event_type == "comment_created" and post_id in (set(SEED_POSTS) | set(dynamic_by_id)):
        return (event_type, post_token, str(event.get("text") or ""))
    if event_type == "profile_updated":
        return (
            event_type,
            str(event.get("displayName") or ""),
            str(event.get("bio") or ""),
            str(event.get("avatar") or ""),
        )
    return None


